// =====================================================================
//  A Corps - Accordeur & Solfege (V2)   lanceur autonome
//  Sert l'application sur 127.0.0.1 (contexte securise : le micro
//  fonctionne) puis ouvre le navigateur par defaut.
// =====================================================================
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Diagnostics;

class ACorps
{
    const string B64 =
    "";

    static void Main()
    {
        byte[] body = Convert.FromBase64String(B64);
        TcpListener srv = null;
        int port = 8731;
        for (int p = port; p < port + 30; p++)
        {
            try { srv = new TcpListener(IPAddress.Loopback, p); srv.Start(); port = p; break; }
            catch { srv = null; }
        }
        if (srv == null)
        {
            Console.WriteLine("Aucun port disponible. Fermez d'autres applications et reessayez.");
            Console.ReadLine();
            return;
        }
        string url = "http://127.0.0.1:" + port + "/";
        Console.WriteLine();
        Console.WriteLine("   A Corps est lance !");
        Console.WriteLine("   Adresse : " + url);
        Console.WriteLine();
        Console.WriteLine("   Laissez cette fenetre ouverte pendant l'utilisation.");
        Console.WriteLine("   Fermez cette fenetre pour quitter l'application.");
        Console.WriteLine();
        try { Process.Start(new ProcessStartInfo(url) { UseShellExecute = true }); }
        catch { Console.WriteLine("   Ouvrez l'adresse ci-dessus manuellement dans votre navigateur."); }

        byte[] header = Encoding.ASCII.GetBytes(
            "HTTP/1.1 200 OK\r\n" +
            "Content-Type: text/html; charset=utf-8\r\n" +
            "Content-Length: " + body.Length + "\r\n" +
            "Cache-Control: no-store\r\n" +
            "Connection: close\r\n\r\n");

        while (true)
        {
            try
            {
                using (TcpClient c = srv.AcceptTcpClient())
                using (NetworkStream ns = c.GetStream())
                {
                    byte[] tmp = new byte[4096];
                    try { ns.ReadTimeout = 250; ns.Read(tmp, 0, tmp.Length); } catch { }
                    ns.Write(header, 0, header.Length);
                    ns.Write(body, 0, body.Length);
                    ns.Flush();
                }
            }
            catch { }
        }
    }
}
